function nextGreaterElements(nums) {
  const n = nums.length, ans = new Array(n).fill(-1), st = [];
  for (let i = 2 * n - 1; i >= 0; i--) {
    const x = nums[i % n];
    while (st.length && st[st.length - 1] <= x) st.pop();
    if (i < n && st.length) ans[i] = st[st.length - 1];
    st.push(x);
  }
  return ans;
}
